       return `
         <div class="page-shell">
           <main id="main-content">
             <section class="card" aria-labelledby="page-title">
               <div class="hero">
                 <p class="eyebrow">Notification settings</p>
                 <h1 id="page-title">Choose your updates</h1>
                 <p class="intro">Select how product alerts and important account updates should reach you.</p>
               </div>
               ${NotificationForm()}
             </section>
           </main>
         </div>
       `;
     }

     document.getElementById('root').innerHTML = App();

     document.getElementById('notification-form').addEventListener('submit', (event) => {
       event.preventDefault();

       if (!event.currentTarget.reportValidity()) {
         return;
       }

       const selected = event.currentTarget.elements.notificationPreference.value;
       const option = notificationOptions.find((item) => item.value === selected);
       document.getElementById('form-status').textContent = `Preference saved: ${option.label}.`;
     });
   </script>
