       background: var(--primary-dark);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid #0f62fe;
       outline-offset: 3px;
     }

     .status-message {
       min-height: 1.5rem;
       margin: 0;
       color: var(--primary-dark);
       font-weight: 700;
     }

     @media (max-width: 36rem) {
       .page-shell {
         padding: 1rem;
       }

       .card {
         border-radius: 18px;
       }

       .actions {
         align-items: stretch;
         flex-direction: column;
       }

