 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <div id="root"></div>

   <script>
     const notificationOptions = [
       { id: 'notification-email', value: 'email', label: 'Email' },
       { id: 'notification-sms', value: 'sms', label: 'SMS' },
       { id: 'notification-push', value: 'push', label: 'Push Notifications' },
     ];

     function RadioOption({ id, value, label }) {
       return `
         <div class="radio-option">
           <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
           <label for="${id}">${label}</label>
         </div>
       `;
     }

     function NotificationForm() {
       return `
         <form id="notification-form">
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

           <div class="form-field">
             <fieldset class="radio-fieldset" aria-describedby="notification-help">
               <legend>How do you prefer to receive notifications? <span class="required-marker" aria-hidden="true">*</span></legend>
               <p class="field-help" id="notification-help">Choose one notification channel.</p>
               <div class="radio-grid">
                 ${notificationOptions.map(RadioOption).join('')}
               </div>
             </fieldset>
           </div>

           <div class="actions">
             <button type="submit">Save preference</button>
             <p class="status-message" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       `;
     }

     function App() {
       return `
         <div class="page-shell">
           <main id="main-content">
             <section class="card" aria-labelledby="page-title">
               <div class="hero">
                 <p class="eyebrow">Notification settings</p>
                 <h1 id="page-title">Choose your updates</h1>
                 <p class="intro">Select how product alerts and important account updates should reach you.</p>
               </div>
               ${NotificationForm()}
             </section>
           </main>
         </div>
       `;
     }

     document.getElementById('root').innerHTML = App();

     document.getElementById('notification-form').addEventListener('submit', (event) => {
       event.preventDefault();

       if (!event.currentTarget.reportValidity()) {
         return;
       }

       const selected = event.currentTarget.elements.notificationPreference.value;
       const option = notificationOptions.find((item) => item.value === selected);
       document.getElementById('form-status').textContent = `Preference saved: ${option.label}.`;
     });
   </script>
 </body>
